package com.rationportal.controller; import com.rationportal.model.RationCard; import com.rationportal.service.RationCardService; import org.springframework.http.ResponseEntity; import org.springframework.web.bind.annotation.*; import org.springframework.lang.NonNull; import java.util.List; @RestController @RequestMapping("/api/ration-cards") public class RationCardController { private final RationCardService service; public RationCardController(RationCardService service){this.service=service;} @GetMapping public List<RationCard> getAll(){return service.getAll();} @GetMapping("/{number}") public ResponseEntity<RationCard> getByNumber(@PathVariable String number){RationCard card=service.getByNumber(number); return card==null ? ResponseEntity.notFound().build() : ResponseEntity.ok(card);} @PostMapping public RationCard create(@RequestBody @NonNull RationCard card){return service.save(card);} }